// The typed client of the server (src/generated/hydra-server-client.ts, generated by the SDK from the server contract) with the transport of this app: the
// request goes through apiUrl() and authFetch() like every other call, a refusal of the server is thrown as a ServerHttpError that keeps the status, and an
// answer that is not JSON is delivered as null so the readers of the app decide what to do with it. Routes are moved here from hand-written calls a few at a time.
import { HydraServerClient, type HydraReply, type HydraRequest, type HydraTransport } from '../generated/hydra-server-client';
import { apiUrl } from './apiBase';
import { authFetch } from './session';

/** The server answered with a status that is not a success; the body it sent (null when it was not JSON) and its Retry-After header stay with the error. */
export class ServerHttpError extends Error {
  readonly status: number;
  readonly body: unknown;
  readonly retryAfter: string | null;

  constructor(status: number, body: unknown = null, retryAfter: string | null = null) {
    super(`HTTP ${status}`);
    this.name = 'ServerHttpError';
    this.status = status;
    this.body = body;
    this.retryAfter = retryAfter;
  }
}

/** The path of the request with its query string (empty values are left out). */
export function requestUrl(request: Pick<HydraRequest, 'path' | 'query'>): string {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(request.query)) {
    if (value !== '') params.set(key, value);
  }
  const query = params.toString();
  return apiUrl(query ? `${request.path}?${query}` : request.path);
}

/** A transport over the given fetch function (the session one in the app, a stand-in in the tests). */
export function makeTransport(send: (url: string, init: RequestInit) => Promise<Response> = (url, init) => authFetch(url, init)): HydraTransport {
  return async (request) => {
    const init: RequestInit = { method: request.method };
    // the headers the contract declares for the route (If-Match, X-Controller-Id, X-Correlation-Id) go out with the request
    const headers: Record<string, string> = { ...request.headers };
    if (request.body !== undefined) {
      headers['Content-Type'] = request.contentType ?? 'application/json';
      // an image goes in a real Blob: a newer DOM lib types a Uint8Array as possibly shared, which BodyInit does not accept, and slice() copies it into an ordinary buffer
      init.body = request.contentType === undefined ? JSON.stringify(request.body) : new Blob([(request.body as Uint8Array).slice()]);
    }
    if (Object.keys(headers).length > 0) init.headers = headers;
    const res = await send(requestUrl(request), init);
    if (!res.ok) throw new ServerHttpError(res.status, await Promise.resolve().then(() => res.json()).catch(() => null), res.headers?.get('Retry-After') ?? null);
    const body = request.responseType === 'text' ? await res.text()
      : request.responseType === 'binary' ? new Uint8Array(await res.arrayBuffer())
        : await Promise.resolve().then(() => res.json()).catch(() => null);
    // a WithHeaders call gets the body together with the response headers the contract names for the route
    if (request.replyHeaders) {
      const found: Record<string, string> = {};
      for (const name of request.replyHeaders) {
        const value = res.headers?.get(name);
        if (value !== null && value !== undefined) found[name] = value;
      }
      return { body, headers: found } satisfies HydraReply<unknown>;
    }
    return body;
  };
}

/** Runs a call of the client and hands back the status and the body of the answer: a refusal of the server (a ServerHttpError) becomes its status and the body it sent, a success is 200,
 *  and anything else (the network) is thrown for the caller to treat as a lost connection. The body is null when the answer was not JSON. */
export async function settle(run: () => Promise<unknown>): Promise<{ status: number; data: unknown }> {
  try {
    return { status: 200, data: (await run()) ?? null };
  } catch (error) {
    if (error instanceof ServerHttpError) return { status: error.status, data: error.body ?? null };
    throw error;
  }
}

/** The answer of GET /api/settings: the status, the tree (null when the answer was not JSON or a refusal) and the revision (ETag) the server sent with it. */
export interface SettingsRead { status: number; data: unknown; etag: string | null }

/** Reads the shared settings through the typed client together with the ETag of the answer (kept to send it back as If-Match when the tree is saved). */
export async function readSettings(client: HydraServerClient = serverClient): Promise<SettingsRead> {
  const { status, data } = await settle(() => client.getSettingsWithHeaders());
  if (status !== 200) return { status, data, etag: null };
  const reply = data as HydraReply<unknown> | null;
  return { status, data: reply?.body ?? null, etag: reply?.headers?.ETag ?? null };
}

/** A client whose requests carry the given bearer token, for the callers that are handed their token instead of reading the one of the session (without a token the request leaves with no Authorization header). */
export function makeTokenClient(token: string | null | undefined): HydraServerClient {
  return makeClient((url, init) => fetch(url, { ...init, headers: { ...(init.headers as Record<string, string> | undefined), ...(token ? { Authorization: `Bearer ${token}` } : {}) } }));
}

/** A client over the given fetch function (the session one when none is given); the tests of the readers hand in their own. */
export function makeClient(send?: (url: string, init: RequestInit) => Promise<Response>): HydraServerClient {
  return send ? new HydraServerClient(makeTransport(send)) : serverClient;
}

/** The client every migrated call of the app uses. */
export const serverClient = new HydraServerClient(makeTransport());
